#include <iostream>
#include "streamfind/mass_spec/reader.hpp"
#ifndef STREAMFIND_SCIEX_WIFF_FIXTURE
#error STREAMFIND_SCIEX_WIFF_FIXTURE is required
#endif
int main(){try{mass_spec::reader::MASS_SPEC_FILE file(STREAMFIND_SCIEX_WIFF_FIXTURE);if(file.get_number_spectra()!=8964){std::cerr<<file.get_number_spectra()<<std::endl;return 1;}if(file.get_number_chromatograms()!=0||file.get_number_spectra_binary_arrays()!=17928||file.get_type()!="MS")return 2;auto h=file.get_spectra_headers({0,21});if(h.size()!=2||h.array_length[0]!=-1||h.array_length[1]!=-1)return 3;auto index=file.get_spectra_index({0,21});auto arrays=file.get_spectra_array_length({0,21});auto levels=file.get_spectra_level({0,21});auto rt=file.get_spectra_rt({0,21});if(index.size()!=2||arrays.size()!=2||levels.size()!=2||rt.size()!=2||index[0]!=h.index[0]||arrays[0]!=h.array_length[0]||levels[0]!=h.level[0]||rt[0]!=h.rt[0])return 4;auto spectrum=file.get_spectrum(0);if(spectrum.binary_data.size()!=2||spectrum.binary_data[0].empty()||spectrum.binary_data[0].size()!=spectrum.binary_data[1].size())return 5;auto a=file.get_spectra({0});if(a.size()!=1||a[0].size()!=2||a[0][0].empty()||a[0][0].size()!=a[0][1].size())return 6;if(file.get_min_mz()!=0||file.get_max_mz()!=0)return 7;auto summary=file.get_summary();if(summary.min_mz!=file.get_min_mz()||summary.max_mz!=file.get_max_mz())return 8;return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 9;}}
